import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv_transpose3d_kernel(
    .param .u64 param_input,
    .param .u64 param_weight,
    .param .u64 param_output,
    .param .u32 param_n
)
{
    .reg .b32 %r<232>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<40>;
    .reg .pred %p<60>;
    .shared .align 16 .f32 sharedRow[64];
    .shared .align 4 .f32 sharedWeightCache[24];
    ld.param.u64 %rd1, [param_input];
    ld.param.u64 %rd2, [param_weight];
    ld.param.u64 %rd3, [param_output];
    ld.param.u32 %r1, [param_n];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r2, %ctaid.x;       // block index (b,oc_group,od,oh) flattened
    mov.u32 %r3, %tid.x;         // raw tid in [0, 66*OCB - 1]
    setp.ge.u32 %p16, %r3, 176;
    @%p16 bra EARLY_RET;
    mov.u32 %r90, 22;
    div.u32 %r91, %r3, %r90;     // oc_local
    rem.u32 %r92, %r3, %r90;     // ow_group (0..21)
    mul.lo.u32 %r92, %r92, 3;    // ow0 = ow_group*3; thread computes ow0, ow0+1, ow0+2
    // Decode block index -> oh, od, oc_group, b  (Do=Ho=66, OC_GROUPS=6, OCB=8)
    mov.u32 %r10, 66;
    div.u32 %r11, %r2, %r10;
    rem.u32 %r12, %r2, %r10;      // oh
    mov.u32 %r13, 66;
    div.u32 %r14, %r11, %r13;
    rem.u32 %r15, %r11, %r13;     // od
    mov.u32 %r16, 6;
    div.u32 %r17, %r14, %r16;     // b
    rem.u32 %r18, %r14, %r16;     // oc_group
    // oc = oc_group*OCB + oc_local
    mov.u32 %r19, 8;
    mul.lo.u32 %r93, %r18, %r19;
    add.u32 %r94, %r93, %r91;     // oc
    // bInBase = b * (InC*D*H*W) = b * 12582912
    mov.u32 %r20, 12582912;
    mul.lo.u32 %r21, %r17, %r20;
    // ocBase = oc * 27
    mov.u32 %r22, 27;
    mul.lo.u32 %r23, %r94, %r22;
    mov.f32 %f1, 0f00000000;
    mov.f32 %f0, 0f00000000;
    mov.f32 %f10, 0f00000000;
    mov.u32 %r30, 0;   // ic
IC_LOOP:
    setp.ge.u32 %p1, %r30, 48;
    @%p1 bra IC_DONE;
    // inputBase = bInBase + ic*262144
    mov.u32 %r31, 262144;
    mul.lo.u32 %r32, %r30, %r31;
    add.u32 %r33, %r21, %r32;
    // weightBase = ic*1296 + ocBase
    mov.u32 %r34, 1296;
    mul.lo.u32 %r35, %r30, %r34;
    add.u32 %r36, %r35, %r23;
    mov.u32 %r40, 0;   // kd
KD_LOOP:
    setp.ge.u32 %p2, %r40, 3;
    @%p2 bra KD_DONE;
    sub.s32 %r41, %r15, %r40;     // id = od - kd
    setp.lt.s32 %p3, %r41, 0;
    setp.ge.s32 %p4, %r41, 64;
    or.pred %p5, %p3, %p4;
    @%p5 bra KD_NEXT;
    mov.u32 %r42, 4096;
    mul.lo.u32 %r43, %r41, %r42;
    add.u32 %r44, %r33, %r43;     // inputDBase
    mov.u32 %r45, 9;
    mul.lo.u32 %r46, %r40, %r45;
    add.u32 %r47, %r36, %r46;     // weightDBase
    mov.u32 %r50, 0;   // kh
KH_LOOP:
    setp.ge.u32 %p6, %r50, 3;
    @%p6 bra KH_DONE;
    sub.s32 %r51, %r12, %r50;     // ih = oh - kh
    setp.lt.s32 %p7, %r51, 0;
    setp.ge.s32 %p8, %r51, 64;
    or.pred %p9, %p7, %p8;
    @%p9 bra KH_NEXT;
    mov.u32 %r52, 64;
    mul.lo.u32 %r53, %r51, %r52;
    add.u32 %r54, %r44, %r53;     // inputHBase (row start index)
    mov.u32 %r55, 3;
    mul.lo.u32 %r56, %r50, %r55;
    add.u32 %r57, %r47, %r56;     // weightHBase
    // Cooperative load of weight values for this (ic, kd, kh) across OCB output
    // channels into shared memory; reused by all 66 ow-threads sharing an oc_local,
    // eliminating redundant repeated global loads of the same weight scalar.
    setp.ge.u32 %p15, %r3, 24;
    @%p15 bra SKIP_WEIGHT_LOAD;
    mov.u32 %r100, 3;
    div.u32 %r101, %r3, %r100;      // oc_local_w
    rem.u32 %r102, %r3, %r100;      // kw_w
    add.u32 %r105, %r93, %r101;     // oc_w = oc_group*OCB + oc_local_w
    mov.u32 %r106, 27;
    mul.lo.u32 %r107, %r105, %r106; // ocBase_w
    add.u32 %r108, %r35, %r107;     // + ic*1296
    mov.u32 %r109, 9;
    mul.lo.u32 %r110, %r40, %r109;  // kd*9
    add.u32 %r111, %r108, %r110;
    mov.u32 %r112, 3;
    mul.lo.u32 %r113, %r50, %r112;  // kh*3
    add.u32 %r114, %r111, %r113;
    add.u32 %r115, %r114, %r102;    // + kw_w -> weight global index
    mul.wide.u32 %rd16, %r115, 4;
    add.s64 %rd17, %rd2, %rd16;
    ld.global.f32 %f6, [%rd17];
    mov.u32 %r116, sharedWeightCache;
    mad.lo.s32 %r117, %r3, 4, %r116;
    st.shared.f32 [%r117], %f6;
SKIP_WEIGHT_LOAD:
    // Cooperative load of the full input row (64 elems) into shared memory.
    // Only the oc_local == 0 group (raw tid < 64) performs the load;
    // it is reused by all OCB output-channel groups sharing this CTA,
    // cutting redundant global loads of the same input row by 8x.
    setp.ge.u32 %p10, %r3, 16;
    @%p10 bra SKIP_LOAD;
    mad.lo.s32 %r60, %r3, 4, %r54;   // vectorized: 16 threads x 4 floats = 64 elems
    mul.wide.u32 %rd10, %r60, 4;
    add.s64 %rd11, %rd1, %rd10;
    ld.global.v4.f32 {%f2, %f3, %f7, %f8}, [%rd11];
    mov.u32 %r61, sharedRow;
    mad.lo.s32 %r62, %r3, 16, %r61;
    st.shared.v4.f32 [%r62], {%f2, %f3, %f7, %f8};
SKIP_LOAD:
    bar.sync 0;
    add.u32 %r200, %r92, 1;        // ow1 = ow0+1
    add.u32 %r201, %r92, 2;        // ow2 = ow0+2
    sub.s32 %r230, %r92, 1;        // ow0-1
    sub.s32 %r231, %r92, 2;        // ow0-2
    mov.u32 %r202, 3;
    mul.lo.u32 %r203, %r91, %r202; // wbase = oc_local*3
    mov.u32 %r204, sharedRow;
    mov.u32 %r205, sharedWeightCache;
    // Load the 3 weights for this oc_local once (contiguous, no bounds needed).
    mad.lo.s32 %r209, %r203, 4, %r205;
    ld.shared.f32 %f23, [%r209];
    add.u32 %r214, %r203, 1;
    mad.lo.s32 %r215, %r214, 4, %r205;
    ld.shared.f32 %f27, [%r215];
    add.u32 %r221, %r203, 2;
    mad.lo.s32 %r222, %r221, 4, %r205;
    ld.shared.f32 %f31, [%r222];
    // Load the 5 unique shared-row values needed by the 3-wide output tile
    // once each, instead of the previous 9 redundant per-tap loads.
    // v0 = row[ow0] (always within [0,64))
    mad.lo.s32 %r206, %r92, 4, %r204;
    ld.shared.f32 %f20, [%r206];
    // vp1 = row[ow0+1]
    setp.ge.s32 %p33, %r200, 64;
    mov.f32 %f21, 0f00000000;
    @%p33 bra VP1_DONE;
    mad.lo.s32 %r207, %r200, 4, %r204;
    ld.shared.f32 %f21, [%r207];
VP1_DONE:
    // vp2 = row[ow0+2]
    setp.ge.s32 %p36, %r201, 64;
    mov.f32 %f22, 0f00000000;
    @%p36 bra VP2_DONE;
    mad.lo.s32 %r208, %r201, 4, %r204;
    ld.shared.f32 %f22, [%r208];
VP2_DONE:
    // vm1 = row[ow0-1]
    setp.lt.s32 %p39, %r230, 0;
    mov.f32 %f24, 0f00000000;
    @%p39 bra VM1_DONE;
    mad.lo.s32 %r211, %r230, 4, %r204;
    ld.shared.f32 %f24, [%r211];
VM1_DONE:
    // vm2 = row[ow0-2]
    setp.lt.s32 %p42, %r231, 0;
    mov.f32 %f28, 0f00000000;
    @%p42 bra VM2_DONE;
    mad.lo.s32 %r217, %r231, 4, %r204;
    ld.shared.f32 %f28, [%r217];
VM2_DONE:
    // kw = 0 contributions
    fma.rn.f32 %f1, %f20, %f23, %f1;
    fma.rn.f32 %f0, %f21, %f23, %f0;
    fma.rn.f32 %f10, %f22, %f23, %f10;
    // kw = 1 contributions
    fma.rn.f32 %f1, %f24, %f27, %f1;
    fma.rn.f32 %f0, %f20, %f27, %f0;
    fma.rn.f32 %f10, %f21, %f27, %f10;
    // kw = 2 contributions
    fma.rn.f32 %f1, %f28, %f31, %f1;
    fma.rn.f32 %f0, %f24, %f31, %f0;
    fma.rn.f32 %f10, %f20, %f31, %f10;
    bar.sync 0;
KH_NEXT:
    add.u32 %r50, %r50, 1;
    bra KH_LOOP;
KH_DONE:
KD_NEXT:
    add.u32 %r40, %r40, 1;
    bra KD_LOOP;
KD_DONE:
    add.u32 %r30, %r30, 1;
    bra IC_LOOP;
IC_DONE:
    // output linear index = (((b*48+oc)*66+od)*66+oh)*66+ow
    mov.u32 %r80, 48;
    mul.lo.u32 %r81, %r17, %r80;
    add.u32 %r82, %r81, %r94;      // b*48+oc
    mov.u32 %r83, 66;
    mul.lo.u32 %r84, %r82, %r83;
    add.u32 %r85, %r84, %r15;      // (...)* 66 + od
    mul.lo.u32 %r86, %r85, %r83;
    add.u32 %r87, %r86, %r12;      // (...)*66 + oh
    mul.lo.u32 %r88, %r87, %r83;
    add.u32 %r89, %r88, %r92;      // (...)*66 + ow0
    mul.wide.u32 %rd14, %r89, 4;
    add.s64 %rd15, %rd3, %rd14;
    st.global.f32 [%rd15], %f1;
    add.u32 %r95, %r89, 1;         // ow1 = ow0 + 1
    mul.wide.u32 %rd18, %r95, 4;
    add.s64 %rd19, %rd3, %rd18;
    st.global.f32 [%rd19], %f0;
    add.u32 %r128, %r89, 2;        // ow2 = ow0 + 2
    mul.wide.u32 %rd20, %r128, 4;
    add.s64 %rd21, %rd3, %rd20;
    st.global.f32 [%rd21], %f10;
EARLY_RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        # Preserve exact reference constructor/parameter behavior (init scheme etc.)
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose3d.weight
        x = x.contiguous()
        weight = weight.contiguous()

        B, InC, D, H, W = x.shape
        OutC = self.conv_transpose3d.out_channels
        K = self.conv_transpose3d.kernel_size[0]
        stride = self.conv_transpose3d.stride[0]
        padding = self.conv_transpose3d.padding[0]
        output_padding = self.conv_transpose3d.output_padding[0]

        D_out = (D - 1) * stride - 2 * padding + K + output_padding
        H_out = (H - 1) * stride - 2 * padding + K + output_padding
        W_out = (W - 1) * stride - 2 * padding + K + output_padding

        output = torch.empty((B, OutC, D_out, H_out, W_out),
                              device=x.device, dtype=x.dtype)

        B_, OutC_, D_out_, H_out_, W_out_ = output.shape
        OCB = 8
        OC_GROUPS = OutC_ // OCB
        num_rows = B_ * OC_GROUPS * D_out_ * H_out_
        N = output.numel()
        module = _get_ptx_module()
        OW_TILE = 3
        threads_per_block = (W_out_ // OW_TILE) * OCB
        block_dim = ((threads_per_block + 31) // 32) * 32
        block = (block_dim, 1, 1)
        grid = (num_rows, 1, 1)
        module.launch(
            "conv_transpose3d_kernel",
            grid=grid,
            block=block,
            arguments=[x, weight, output, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

